# The convex overlap-area templates of lib/geometry.esm against the
# `polygon_intersection_area` leaf.
#
# Every polygon pair of tests/conformance/geometry_templates/pairs.json (the cell
# pairs the repository's polygon and regridding documents clip, generated by
# scripts/gen-geometry-template-pairs.py) runs through the expanded template
# (`overlap_area_planar`, or `overlap_area_spherical` over unit vectors built with
# `lonlat_to_unit`) under the interpreter, and through the leaf (the planar
# Sutherland-Hodgman clip, the GeometryOps spherical clip). The template must agree
# with the leaf and with the pair's exact / 40-digit reference area within the
# CONFORMANCE_SPEC §5.8.2 tolerance and give the planar reference exactly on a
# pair of cells from one grid, with every ring padded by repeated vertices to a
# common slot count.

using Test
using JSON3
using EarthSciAST
import GeometryOps  # with GeoInterface: the spherical leaf (EarthSciASTGeometryOpsExt)
import GeoInterface
import OrdinaryDiffEqTsit5  # the solver `run_inline_tests` picks

include("testutils.jl")  # TESTUTILS_REPO_ROOT

const _GT_LIB = joinpath(TESTUTILS_REPO_ROOT, "lib", "geometry.esm")
const _GT_PAIRS = JSON3.read(
    read(joinpath(TESTUTILS_REPO_ROOT, "tests", "conformance", "geometry_templates", "pairs.json"), String)
)
const _GT_RTOL = Float64(_GT_PAIRS.tolerance.rtol)
const _GT_ATOL_FACTOR = Float64(_GT_PAIRS.tolerance.atol_factor)

_gt_const(a) = Dict{String, Any}("op" => "const", "args" => Any[], "value" => a)
_gt_apply(name, bindings) = Dict{String, Any}(
    "op" => "apply_expression_template", "args" => Any[], "name" => name, "bindings" => bindings
)
_gt_plain(x) = x isa JSON3.Array ? Any[_gt_plain(v) for v in x] : (x isa Real ? Float64(x) : x)

# The template areas. The interpreter build compiles a `faq` body once per output
# cell, at ~0.3 s and ~45 MB a cell for the planar template and several times
# that on the sphere, so this suite takes a sample of each group: its first pair
# and its first same-grid pair, all groups of one manifold in a single `faq`
# over a pair axis. Row k of `ra`/`rb` holds pair k's two rings, each padded to
# the widest ring by repeating its last vertex (which the template must ignore
# exactly). The Python and Rust suites evaluate every pair, and the padded
# groups' bit equality.
function _gt_sample(g)
    first_same = findfirst(pr -> pr.same_grid, g.pairs)
    picks = first_same === nothing || first_same == 1 ? [1] : [1, first_same]
    return [g.pairs[n] for n in picks]
end

_gt_faq(out, ranges, expr) = Dict{String, Any}(
    "op" => "faq", "args" => Any[], "output_idx" => out, "ranges" => ranges, "expr" => expr
)
_gt_from(s) = Dict{String, Any}("from" => s)
_gt_pad(ring, n) = vcat(Any[Any[Float64(p[1]), Float64(p[2])] for p in ring],
    Any[Any[Float64(ring[end][1]), Float64(ring[end][2])] for _ in (length(ring) + 1):n])

function _gt_document(manifold, rows)
    nv = maximum(max(length(g.ring_a[pr.i]), length(g.ring_b[pr.j])) for (g, pr) in rows)
    ra = Any[_gt_pad(g.ring_a[pr.i], nv) for (g, pr) in rows]
    rb = Any[_gt_pad(g.ring_b[pr.j], nv) for (g, pr) in rows]
    K = length(rows)
    index_sets = Dict{String, Any}(
        "pairs" => Dict{String, Any}("kind" => "interval", "size" => K),
        "verts" => Dict{String, Any}("kind" => "interval", "size" => nv),
        "xyz" => Dict{String, Any}("kind" => "interval", "size" => 3)
    )
    vars = Dict{String, Any}(
        "S" => Dict{String, Any}("type" => "unknown", "units" => "1", "default" => 0.0, "shape" => Any["pairs"])
    )
    eqs = Any[]
    for (x, stack) in (("ra", ra), ("rb", rb))
        vars[x] = Dict{String, Any}("type" => "unknown", "units" => "1", "shape" => Any["pairs", "verts", "xy"])
        push!(eqs, Dict{String, Any}("lhs" => x, "rhs" => _gt_const(stack)))
    end
    index_sets["xy"] = Dict{String, Any}("kind" => "interval", "size" => 2)
    a, b, name = "ra", "rb", "overlap_area_planar"
    if manifold != "planar"
        name = "overlap_area_spherical"
        for (x, ring) in (("xa", a), ("xb", b))
            vars[x] = Dict{String, Any}("type" => "unknown", "units" => "1", "shape" => Any["pairs", "verts", "xyz"])
            push!(eqs, Dict{String, Any}(
                "lhs" => x,
                "rhs" => _gt_faq(Any["c", "v", "d"],
                    Dict{String, Any}("c" => _gt_from("pairs"), "v" => _gt_from("verts"), "d" => _gt_from("xyz")),
                    _gt_apply("lonlat_to_unit", Dict{String, Any}("ring" => ring, "cell" => "c", "vert" => "v", "comp" => "d")))
            ))
        end
        a, b = "xa", "xb"
    end
    ranges = Dict{String, Any}("k" => _gt_from("pairs"))
    push!(eqs, Dict{String, Any}(
        "lhs" => _gt_faq(Any["k"], ranges,
            Dict{String, Any}("op" => "D", "args" => Any[Dict{String, Any}("op" => "index", "args" => Any["S", "k"])], "wrt" => "t")),
        "rhs" => _gt_faq(Any["k"], ranges, _gt_apply(name, Dict{String, Any}(
            "ring_a" => a, "cell_a" => "k", "nv_a" => nv, "ring_b" => b, "cell_b" => "k", "nv_b" => nv)))
    ))
    return Dict{String, Any}(
        "esm" => "1.1.0",
        "metadata" => Dict{String, Any}("name" => "geometry_template_probe", "authors" => Any["t"]),
        "index_sets" => index_sets,
        "models" => Dict{String, Any}("M" => Dict{String, Any}(
            "expression_template_imports" => Any[Dict{String, Any}("ref" => "geometry.esm")],
            "variables" => vars, "equations" => eqs)))
end

function _gt_template_values()
    out = Dict{String, Dict{Tuple{Int, Int}, Float64}}()
    for manifold in ("planar", "spherical")
        rows = [(g, pr) for g in _GT_PAIRS.groups if g.manifold == manifold && !haskey(g, :padding_of)
                for pr in _gt_sample(g)]
        isempty(rows) && continue
        file = load_string(JSON3.write(_gt_document(manifold, rows)); base_path = dirname(_GT_LIB))
        f!, u0, p, _, vm = EarthSciAST._build_evaluator(file; compiler = :interpreter)
        du = similar(u0)
        f!(du, u0, p, 0.0)
        for (k, (g, pr)) in enumerate(rows)
            get!(out, String(g.id), Dict{Tuple{Int, Int}, Float64}())[(pr.i, pr.j)] = du[vm["S[$k]"]]
        end
    end
    return out
end

_gt_ring(stack, k) = permutedims(reduce(hcat, [Float64[p[1], p[2]] for p in stack[k]]))

# The leaf's area, or `nothing` when it refuses an operand.
function _gt_leaf(g, pr)
    try
        ring = EarthSciAST.intersect_polygon(_gt_ring(g.ring_a, pr.i), _gt_ring(g.ring_b, pr.j), String(g.manifold))
        size(ring, 1) < 3 && return 0.0
        return EarthSciAST.polygon_area(ring, String(g.manifold))
    catch e
        e isa EarthSciAST.GeometryError || rethrow()
        return nothing
    end
end

function _gt_atol(g)
    g.manifold != "planar" && return _GT_ATOL_FACTOR
    m = 1.0
    for stack in (g.ring_a, g.ring_b), r in stack, p in r, x in p
        m = max(m, abs(Float64(x)))
    end
    return _GT_ATOL_FACTOR * m^2
end

@testset "lib/geometry.esm templates agree with polygon_intersection_area" begin
    tvals = _gt_template_values()
    for g in _GT_PAIRS.groups
        haskey(g, :padding_of) && continue
        gid = String(g.id)
        atol = _gt_atol(g)
        @testset "$gid" begin
            max_ref = 0.0
            max_leaf = 0.0
            for pr in _gt_sample(g)
                t = tvals[gid][(pr.i, pr.j)]  # every group has a pair
                @test isfinite(t)
                ref = pr.reference
                if ref !== nothing
                    @test abs(t - ref) <= atol + _GT_RTOL * abs(ref)
                    max_ref = max(max_ref, abs(t - ref))
                    if pr.same_grid && g.manifold == "planar"
                        @test t === Float64(ref)
                    end
                end
                leaf = _gt_leaf(g, pr)
                if leaf !== nothing
                    @test abs(t - leaf) <= atol + _GT_RTOL * abs(leaf)
                    max_leaf = max(max_leaf, abs(t - leaf))
                end
            end
            get(ENV, "ESM_GEOMETRY_TEMPLATE_REPORT", "") == "1" &&
                println("geometry template ", gid, ": max |template - reference| = ", max_ref,
                    ", max |template - leaf| = ", max_leaf)
        end
    end

    @testset "lonlat_to_unit is the leaf's conversion" begin
        pts = ((0.0, 0.0), (30.0, 45.0), (-120.5, -60.25), (179.9, 89.0))
        ring = Any[Any[Any[lon, lat] for (lon, lat) in pts]]
        vars = Dict{String, Any}()
        eqs = Any[]
        for (k, _) in enumerate(pts), d in 1:3
            v = "u_$(k)_$d"
            vars[v] = Dict{String, Any}("type" => "unknown", "units" => "1", "default" => 0.0)
            push!(eqs, Dict{String, Any}(
                "lhs" => Dict{String, Any}("op" => "D", "args" => Any[v], "wrt" => "t"),
                "rhs" => _gt_apply("lonlat_to_unit",
                    Dict{String, Any}("ring" => _gt_const(ring), "cell" => 1, "vert" => k, "comp" => d))))
        end
        doc = Dict{String, Any}("esm" => "1.1.0",
            "metadata" => Dict{String, Any}("name" => "lonlat_to_unit_probe", "authors" => Any["t"]),
            "models" => Dict{String, Any}("M" => Dict{String, Any}(
                "expression_template_imports" => Any[Dict{String, Any}("ref" => "geometry.esm")],
                "variables" => vars, "equations" => eqs)))
        file = load_string(JSON3.write(doc); base_path = dirname(_GT_LIB))
        f!, u0, p, _, vm = EarthSciAST._build_evaluator(file; compiler = :interpreter)
        du = similar(u0)
        f!(du, u0, p, 0.0)
        for (k, (lon, lat)) in enumerate(pts)
            want = EarthSciAST._lonlat_to_unit(lon, lat)
            for d in 1:3
                @test du[vm["u_$(k)_$d"]] === Float64(want[d])
            end
        end
    end
end
